#include "bell_generator.h"
#include "excitation/meridional_influence.hpp"
#include "fem/internal_modal_solver.hpp"

#include <algorithm>
#include <cmath>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <sstream>
#include <string>
#include <vector>

using namespace BellOptimizer;
namespace {
struct Level { int layers=0; BellMeshData mesh; ModalData modes; };
std::vector<std::string> split(const std::string&s){std::vector<std::string>v;std::stringstream ss(s);std::string x;while(std::getline(ss,x,','))v.push_back(x);return v;}
BellGeometry geometryFrom(const std::vector<std::string>&f){BellGeometry g;g.H=std::stod(f[2]);g.R_mouth=std::stod(f[3]);g.t_top=std::stod(f[4]);g.t_bottom=std::stod(f[5]);g.r_knots={0.0,std::stod(f[6]),std::stod(f[7]),std::stod(f[8]),1.0};g.ellipticity=std::stod(f[9]);return g;}
bool makeLevel(const BellMeshData&base,int n,int layers,const BellMaterial&mat,Level&out){out.mesh.outer_profile=base.outer_profile;out.mesh.inner_profile=base.inner_profile;out.mesh.total_arc_length=base.total_arc_length;out.mesh.min_thickness=base.min_thickness;out.mesh.max_thickness=base.max_thickness;out.mesh.nodes.reserve(std::size_t(n)*std::size_t(layers+1));out.mesh.elements.reserve(std::size_t(n-1)*std::size_t(layers));for(int l=0;l<=layers;++l){double a=double(l)/layers;for(int i=0;i<n;++i){const auto&o=base.outer_profile[std::size_t(i)];const auto&in=base.inner_profile[std::size_t(i)];Node node;node.id=int(out.mesh.nodes.size())+1;node.r=o.r+a*(in.r-o.r);node.z=o.z+a*(in.z-o.z);out.mesh.nodes.push_back(node);}}for(int l=0;l<layers;++l){int ro=l*n,ri=(l+1)*n;for(int i=0;i<n-1;++i){Element e;e.n1=ri+i+1;e.n2=ro+i+1;e.n3=ro+i+2;e.n4=ri+i+2;out.mesh.elements.push_back(e);}}out.layers=layers;InternalModalSolver solver(true,10,true);Excitation::MeridionalInfluence influence;ModalProblem p{out.mesh,mat,".","round_thickness_sweep",&influence};return solver.solve(p,out.modes)&&out.modes.modes.size()>=10;}
struct Shape {double corr=0,error=1;};
Shape compare(const Level&a,const Level&b,int n,int mode){const auto&ma=a.modes.modes[std::size_t(mode)];const auto&mb=b.modes.modes[std::size_t(mode)];double dot=0,na=0,nb=0;std::vector<double>x,y;for(int k=0;k<=4;++k){double t=double(k)/4;for(int i=0;i<n;++i){auto sample=[&](const Level&l,const std::vector<double>&v){double q=t*l.layers;int j0=std::min(l.layers-1,int(std::floor(q)));int j1=std::min(l.layers,j0+1);double a=t>=1?1:q-j0;std::size_t id0=std::size_t(j0*n+i),id1=std::size_t(j1*n+i);return v[id0]+a*(v[id1]-v[id0]);};x.push_back(sample(a,ma.nodal_radial));x.push_back(sample(a,ma.nodal_axial));y.push_back(sample(b,mb.nodal_radial));y.push_back(sample(b,mb.nodal_axial));}}for(std::size_t i=0;i<x.size();++i){dot+=x[i]*y[i];na+=x[i]*x[i];nb+=y[i]*y[i];}if(!(na>0)||!(nb>0))return{};double scale=dot/na,res=0;for(std::size_t i=0;i<x.size();++i){double d=y[i]-scale*x[i];res+=d*d;}return{std::abs(dot)/std::sqrt(na*nb),std::sqrt(res/nb)};}
}
int main(int argc,char**argv){const std::string input=argc>1?argv[1]:"round_geometry_dataset.csv",output=argc>2?argv[2]:"round_geometry_thickness_sweep.csv";const int n=argc>3?std::stoi(argv[3]):41;std::ifstream in(input);if(!in)return 1;std::string line;std::getline(in,line);std::ofstream csv(output);if(!csv)return 2;csv<<"geometry_index,tag,profile_nodes,coarse_layers,fine_layers,mode,coarse_hz,fine_hz,relative_frequency_change,shape_correlation,normalized_shape_l2_error\n"<<std::setprecision(12);BellMaterial mat;const std::vector<int> selected{0,1,2,3,15,30,48,58,63};int geometries=0,failures=0;double global_max=0,global_min_corr=1,global_shape=0;while(std::getline(in,line)){if(line.empty())continue;const auto f=split(line);if(f.size()<17||f[16]!="PASS")continue;const int id=std::stoi(f[0]);if(std::find(selected.begin(),selected.end(),id)==selected.end())continue;const auto g=geometryFrom(f);BellMeshConfig cfg;cfg.nNodes=n;BellGenerator generator(mat,cfg);generator.setGeometry(g);GeometryValidationResult vr;if(!generator.buildMesh(&vr)){++failures;std::cerr<<"BASE_MESH_FAIL "<<id<<' '<<vr.reason<<'\n';continue;}const auto base=generator.getMeshData();std::vector<Level> levels;bool ok=true;for(int layers:{1,2,3,4}){Level l;if(!makeLevel(base,n,layers,mat,l)){ok=false;break;}levels.push_back(std::move(l));}if(!ok){++failures;std::cerr<<"SOLVE_FAIL geometry="<<id<<'\n';continue;}++geometries;for(std::size_t p=1;p<levels.size();++p)for(int m=0;m<10;++m){double fc=levels[p-1].modes.modes[m].frequency_hz,ff=levels[p].modes.modes[m].frequency_hz;double delta=std::abs(ff-fc)/std::max(std::abs(ff),1e-12);auto sh=compare(levels[p-1],levels[p],n,m);global_max=std::max(global_max,delta);global_min_corr=std::min(global_min_corr,sh.corr);global_shape=std::max(global_shape,sh.error);csv<<id<<','<<f[1]<<','<<n<<','<<levels[p-1].layers<<','<<levels[p].layers<<','<<m+1<<','<<fc<<','<<ff<<','<<delta<<','<<sh.corr<<','<<sh.error<<'\n';}}
std::cout<<"profile_nodes="<<n<<" geometries="<<geometries<<" failures="<<failures<<" max_adjacent_frequency_change_percent="<<global_max*100<<" min_shape_correlation="<<global_min_corr<<" max_shape_error_percent="<<global_shape*100<<'\n';return geometries>0&&failures==0&&csv?0:3;}
